INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5990896, 878399, 114056, '<td valign="top">hahahaa i almost did exactly the same thing. great minds think alike. 10.</td>', 'hahahaa i almost did exactly the same thing. great minds think alike. 10.', '2010-05-05 01:08:21.000000', NULL, 1),
(5990921, 877856, 114056, '<td valign="top">I think you need a faster shutter speed here to stop the motion, try dropping your aperture and increasing your ISO so you can get more light through.</td>', 'I think you need a faster shutter speed here to stop the motion, try dropping your aperture and increasing your ISO so you can get more light through.', '2010-05-05 01:10:18.000000', NULL, 1),
(5990935, 877108, 114056, '<td valign="top">Nice depth of field, exposure and colour.</td>', 'Nice depth of field, exposure and colour.', '2010-05-05 01:11:32.000000', NULL, 1),
(5990940, 878209, 114056, '<td valign="top">Very nice, pitty that ghostbusters sign is up in the corner, it''s quite distracting.</td>', 'Very nice, pitty that ghostbusters sign is up in the corner, it''s quite distracting.', '2010-05-05 01:12:31.000000', NULL, 1),
(5990948, 877002, 114056, '<td valign="top">love the facial expressions, really capture the moment!</td>', 'love the facial expressions, really capture the moment!', '2010-05-05 01:13:01.000000', NULL, 1),
(5990950, 878320, 50695, '<td valign="top">I don''t know if I''m voting this challenge, but this is the best race car photo ever.</td>', 'I don''t know if I''m voting this challenge, but this is the best race car photo ever.', '2010-05-05 01:13:09.000000', NULL, 1),
(5990970, 878106, 114056, '<td valign="top">Looks like you''ve done a lot of sharpening to this which is giving little halos around people. Try increasing your ISO (your camera can handle 800 or more without much noise) so you can get your shutter faster.</td>', 'Looks like you''ve done a lot of sharpening to this which is giving little halos around people. Try increasing your ISO (your camera can handle 800 or more without much noise) so you can get your shutter faster.', '2010-05-05 01:15:10.000000', NULL, 1),
(5991097, 878209, 108544, '<td valign="top">Ghostbuster? lol Nice...</td>', 'Ghostbuster? lol Nice...', '2010-05-05 01:31:02.000000', NULL, 1),
(5991118, 876904, 108544, '<td valign="top">Man, this looks so old school! I love how the noise, goes so well with this shot. <br/>Great job!</td>', 'Man, this looks so old school! I love how the noise, goes so well with this shot. Great job!', '2010-05-05 01:33:25.000000', NULL, 1),
(5991124, 878016, 83313, '<td valign="top">Seems quite soft and not showing a lot of detail on the longboat team. I suspect this may be an extreme crop.</td>', 'Seems quite soft and not showing a lot of detail on the longboat team. I suspect this may be an extreme crop.', '2010-05-05 01:34:03.000000', NULL, 1),
(5991152, 878442, 83313, '<td valign="top">Really blurred, which is often a good effect for a sports pic, but I''m afraid it''s not coming off well to me. Also, the subject is in deep shadow, facing away from the sun.</td>', 'Really blurred, which is often a good effect for a sports pic, but I''m afraid it''s not coming off well to me. Also, the subject is in deep shadow, facing away from the sun.', '2010-05-05 01:38:35.000000', NULL, 1),
(5991172, 877240, 83313, '<td valign="top">Lots of noise visible in the sky. That may have been unavoidable without having noise reduction also kill detail in the water. The sky is a little too purpley for my own astes as well.</td>', 'Lots of noise visible in the sky. That may have been unavoidable without having noise reduction also kill detail in the water. The sky is a little too purpley for my own astes as well.', '2010-05-05 01:41:29.000000', NULL, 1),
(5991176, 877773, 83313, '<td valign="top">Wonderful use of motion blur.</td>', 'Wonderful use of motion blur.', '2010-05-05 01:42:02.000000', NULL, 1),
(5991200, 876198, 27133, '<td valign="top">I prefer your FB version...much better colour.</td>', 'I prefer your FB version...much better colour.', '2010-05-05 01:45:13.000000', NULL, 1),
(5991296, 876198, 89223, '<td valign="top">I really like this image, i love the sky and comp of this photo, i feel the wave on the the right takes some attention away from the boarder/rider with motion and sharpness, but great capture!</td>', 'I really like this image, i love the sky and comp of this photo, i feel the wave on the the right takes some attention away from the boarder/rider with motion and sharpness, but great capture!', '2010-05-05 02:00:03.000000', NULL, 1),
(5991338, 878245, 35467, '<td valign="top">Would have been nice to see the rest of the fly .... 9</td>', 'Would have been nice to see the rest of the fly .... 9', '2010-05-05 02:09:53.000000', NULL, 1),
(5991357, 878245, 114285, '<td valign="top">THis is a great shot, should do well.</td>', 'THis is a great shot, should do well.', '2010-05-05 02:13:12.000000', NULL, 1),
(5991358, 878076, 114908, '<td valign="top">The horse and rider are captured nicely, but the sign is distracting.</td>', 'The horse and rider are captured nicely, but the sign is distracting.', '2010-05-05 02:13:16.000000', NULL, 1),
(5991362, 877875, 114285, '<td valign="top">Ohh bet that hurt.</td>', 'Ohh bet that hurt.', '2010-05-05 02:14:00.000000', NULL, 1),
(5991364, 878319, 114908, '<td valign="top">The sky and water are beautiful in this shot.</td>', 'The sky and water are beautiful in this shot.', '2010-05-05 02:14:20.000000', NULL, 1),
(5991366, 878073, 115096, '<td valign="top">Cool shot, but i''m guessing you will get a DQ because of the text...</td>', 'Cool shot, but i''m guessing you will get a DQ because of the text...', '2010-05-05 02:14:47.000000', NULL, 1),
(5991367, 877606, 114285, '<td valign="top">Greact action shot, love the look on the dark blue kids face.</td>', 'Greact action shot, love the look on the dark blue kids face.', '2010-05-05 02:14:51.000000', NULL, 1),
(5991370, 876548, 114285, '<td valign="top">Cool , i feel a ribbon here.</td>', 'Cool , i feel a ribbon here.', '2010-05-05 02:15:55.000000', NULL, 1),
(5991373, 878342, 114908, '<td valign="top">I really like this shot, and it''s very good in black and white, but the lighting is a bit harsh.</td>', 'I really like this shot, and it''s very good in black and white, but the lighting is a bit harsh.', '2010-05-05 02:16:14.000000', NULL, 1),
(5991409, 876570, 114908, '<td valign="top">This is a great capture, but I think it would have been better in black and white.</td>', 'This is a great capture, but I think it would have been better in black and white.', '2010-05-05 02:24:19.000000', NULL, 1),
(5991444, 878320, 114908, '<td valign="top">*GASP* I love Kyle Busch!</td>', '*GASP* I love Kyle Busch!', '2010-05-05 02:34:46.000000', NULL, 1),
(5991530, 878441, 114056, '<td valign="top">Personally, i''m not a fan of the "everything blurred" look, the background blur is great but it would have been nice to have the person sharp. Love the colours.</td>', 'Personally, i''m not a fan of the "everything blurred" look, the background blur is great but it would have been nice to have the person sharp. Love the colours.', '2010-05-05 03:27:49.000000', NULL, 1),
(5991531, 876910, 114056, '<td valign="top">Love the Bokeh depth of field and sharpness.</td>', 'Love the Bokeh depth of field and sharpness.', '2010-05-05 03:28:49.000000', NULL, 1),
(5991536, 878137, 114056, '<td valign="top">Love the look of concentration. I would have liked to see a wider aperture to get the background blurred as it is distracting from your subject (in my opinion).</td>', 'Love the look of concentration. I would have liked to see a wider aperture to get the background blurred as it is distracting from your subject (in my opinion).', '2010-05-05 03:30:23.000000', NULL, 1),
(5991537, 876088, 114056, '<td valign="top">Finally a bowling image, we were joking around the office at the beginning of this challenge that none of the other sports challenges had bowling alleys.<br/> <br/>Interesting idea with the long exposure!</td>', 'Finally a bowling image, we were joking around the office at the beginning of this challenge that none of the other sports challenges had bowling alleys. Interesting idea with the long exposure!', '2010-05-05 03:31:59.000000', NULL, 1),
(5991539, 877984, 114056, '<td valign="top">Looks like a bit of motion blur in here, love the dust cloud though.</td>', 'Looks like a bit of motion blur in here, love the dust cloud though.', '2010-05-05 03:32:48.000000', NULL, 1),
(5991541, 877944, 21714, '<td valign="top">Yep. Hand + Ball = Handball.</td>', 'Yep. Hand + Ball = Handball.', '2010-05-05 03:33:26.000000', NULL, 1),
(5991542, 877622, 21714, '<td valign="top">Not the best of quality, but it''s a very good capture.</td>', 'Not the best of quality, but it''s a very good capture.', '2010-05-05 03:34:25.000000', NULL, 1),
(5991545, 878207, 114056, '<td valign="top">Love the chunks of dirt spraying everywhere.</td>', 'Love the chunks of dirt spraying everywhere.', '2010-05-05 03:34:57.000000', NULL, 1),
(5991546, 878081, 114056, '<td valign="top">Nice action shot</td>', 'Nice action shot', '2010-05-05 03:35:14.000000', NULL, 1),
(5991563, 877710, 21714, '<td valign="top">I like it. Modern version of the discus thrower?</td>', 'I like it. Modern version of the discus thrower?', '2010-05-05 03:44:05.000000', NULL, 1),
(5991568, 876770, 21714, '<td valign="top">Can''t tell whether he''s made it or not. So I say great timing. It makes me want to see the next frame.</td>', 'Can''t tell whether he''s made it or not. So I say great timing. It makes me want to see the next frame.', '2010-05-05 03:47:30.000000', NULL, 1),
(5991571, 877856, 21714, '<td valign="top">Looks like he''s going to fly off from there.</td>', 'Looks like he''s going to fly off from there.', '2010-05-05 03:51:14.000000', NULL, 1),
(5991575, 877306, 21714, '<td valign="top">Love this one. Great timing. Perhaps not the best composition, but I think this is what sports shots should be like. Well done.</td>', 'Love this one. Great timing. Perhaps not the best composition, but I think this is what sports shots should be like. Well done.', '2010-05-05 03:58:15.000000', NULL, 1),
(5991576, 875358, 114056, '<td valign="top">The reflection for me is a little too big and distracting. Playing with your white balance may have given you a more impressive sky.<br/> <br/>Nice idea for a shot however.</td>', 'The reflection for me is a little too big and distracting. Playing with your white balance may have given you a more impressive sky. Nice idea for a shot however.', '2010-05-05 03:58:28.000000', NULL, 1),
(5991577, 877815, 114056, '<td valign="top">Great shot, love the contrast of yellow on blue sky.</td>', 'Great shot, love the contrast of yellow on blue sky.', '2010-05-05 03:58:53.000000', NULL, 1),
(5991588, 877710, 114233, '<td valign="top">LOL - My my my... that is a big stick you have there. 7 for bravery</td>', 'LOL - My my my... that is a big stick you have there. 7 for bravery', '2010-05-05 04:10:41.000000', NULL, 1),
(5991635, 877244, 116105, '<td valign="top">I think this would be a really interesting picture if the bicycle rider hadn''t passed through</td>', 'I think this would be a really interesting picture if the bicycle rider hadn''t passed through', '2010-05-05 05:41:32.000000', NULL, 1),
(5991711, 877751, 23394, '<td valign="top">nice moment, but the key to great sports shots is...<br/> <br/>include the ball</td>', 'nice moment, but the key to great sports shots is... include the ball', '2010-05-05 07:43:59.000000', NULL, 1),
(5991712, 878328, 23394, '<td valign="top">excellent!</td>', 'excellent!', '2010-05-05 07:44:34.000000', NULL, 1),
(5991714, 876904, 23394, '<td valign="top">nice!</td>', 'nice!', '2010-05-05 07:45:47.000000', NULL, 1),
(5991716, 877927, 23394, '<td valign="top">nice idea, but could have been executed much better.  as you''re going for a silhouette and since this is a set up shot, you could have positioned yourself to include the goal, but lose the clutter on the left and right.  keep working at it!</td>', 'nice idea, but could have been executed much better.  as you''re going for a silhouette and since this is a set up shot, you could have positioned yourself to include the goal, but lose the clutter on the left and right.  keep working at it!', '2010-05-05 07:49:52.000000', NULL, 1),
(5991718, 878252, 23394, '<td valign="top">it''s in focus, but i have no idea what you''re after here.</td>', 'it''s in focus, but i have no idea what you''re after here.', '2010-05-05 07:50:51.000000', NULL, 1),
(5991720, 876492, 23394, '<td valign="top">freakin hilarious!</td>', 'freakin hilarious!', '2010-05-05 07:52:23.000000', NULL, 1),
(5991726, 878076, 23394, '<td valign="top">i''m sorry, but all this says to me is that you were there with a camera and something happened in front of you that you weren''t quite prepared for...</td>', 'i''m sorry, but all this says to me is that you were there with a camera and something happened in front of you that you weren''t quite prepared for...', '2010-05-05 07:55:01.000000', NULL, 1),
(5991729, 875992, 23394, '<td valign="top">yippee!  nice shot!</td>', 'yippee!  nice shot!', '2010-05-05 07:57:19.000000', NULL, 1),
(5991730, 877808, 23394, '<td valign="top">nice shot.  i know the tendency is to think you need the whole shot, but i would have cropped it a lot tighter.</td>', 'nice shot.  i know the tendency is to think you need the whole shot, but i would have cropped it a lot tighter.', '2010-05-05 07:58:31.000000', NULL, 1),
(5991732, 876548, 23394, '<td valign="top">dnmc.  yeah, it''s pretty, and yeah precision skydiving is a sport, but simply jumping out of an airplane is no more a sport than taking a bath ;-)</td>', 'dnmc.  yeah, it''s pretty, and yeah precision skydiving is a sport, but simply jumping out of an airplane is no more a sport than taking a bath ;-)', '2010-05-05 08:01:17.000000', NULL, 1),
(5991734, 878012, 23394, '<td valign="top">nice idea, but absolutely no sense of sport...</td>', 'nice idea, but absolutely no sense of sport...', '2010-05-05 08:02:00.000000', NULL, 1),
(5991737, 878338, 23394, '<td valign="top">sorry, but no.  you captured the moment before the real moment.  and the thing about baseball is that you have TONS of moments to go for.  and you have so many different vantage points to shoot from.</td>', 'sorry, but no.  you captured the moment before the real moment.  and the thing about baseball is that you have TONS of moments to go for.  and you have so many different vantage points to shoot from.', '2010-05-05 08:04:17.000000', NULL, 1),
(5991739, 878382, 23394, '<td valign="top">nice work.  i don''t know if it would have been possible to have gotten a lower perspective, but trying to get eye level with your subject makes the difference between a good image and a great one.</td>', 'nice work.  i don''t know if it would have been possible to have gotten a lower perspective, but trying to get eye level with your subject makes the difference between a good image and a great one.', '2010-05-05 08:06:23.000000', NULL, 1),
(5991741, 878181, 23394, '<td valign="top">pretty, but more environmental than sport.</td>', 'pretty, but more environmental than sport.', '2010-05-05 08:07:42.000000', NULL, 1),
(5991748, 876452, 79720, '<td valign="top">I predict a Top 10 for you...maybe even a Top 5. Get your original ready! <b>:</b>-P</td>', 'I predict a Top 10 for you...maybe even a Top 5. Get your original ready! :-P', '2010-05-05 08:13:33.000000', NULL, 1),
(5991749, 877944, 23394, '<td valign="top">there''s promise here.  some things to consider in the future would be to find a perspective that is eye-level or lower, or to get much higher so that you could do something with the shadows, you might get some really interesting shots.  you might also consider toning these to black and white to remove the drab reds and greens (take a look at <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=21714" rel="nofollow" target="_blank">xion</a>''s stuff to see what i mean).</td>', 'there''s promise here.  some things to consider in the future would be to find a perspective that is eye-level or lower, or to get much higher so that you could do something with the shadows, you might get some really interesting shots.  you might also consider toning these to black and white to remove the drab reds and greens (take a look at  xion''s stuff to see what i mean).', '2010-05-05 08:14:37.000000', NULL, 1),
(5991751, 878097, 23394, '<td valign="top">shoot tighter, find a lower perspective, and you''ll capture more intense connections with your subject.</td>', 'shoot tighter, find a lower perspective, and you''ll capture more intense connections with your subject.', '2010-05-05 08:16:16.000000', NULL, 1),
(5991753, 876872, 73942, '<td valign="top">Sorry, not a Yankees fan, but this is an adorable picture.  Here''s a 7 from a Red Sox fan.</td>', 'Sorry, not a Yankees fan, but this is an adorable picture.  Here''s a 7 from a Red Sox fan.', '2010-05-05 08:19:29.000000', NULL, 1),
(5991754, 877884, 23394, '<td valign="top">nice idea, but an imbalanced composition.  also, try to find a lower perspective so that you aren''t shooting down on your subjects; that will establish more of a dynamic connection with the action and give it less of a spectatorish feel.</td>', 'nice idea, but an imbalanced composition.  also, try to find a lower perspective so that you aren''t shooting down on your subjects; that will establish more of a dynamic connection with the action and give it less of a spectatorish feel.', '2010-05-05 08:19:31.000000', NULL, 1),
(5991756, 876872, 23394, '<td valign="top">very, very nice.</td>', 'very, very nice.', '2010-05-05 08:20:37.000000', NULL, 1),
(5991761, 877820, 23394, '<td valign="top">nice colors, but it looks like the image is a little far out of reach.</td>', 'nice colors, but it looks like the image is a little far out of reach.', '2010-05-05 08:22:19.000000', NULL, 1),
(5991762, 878383, 73942, '<td valign="top">Excellent image, the best i''ve seen so far int his challenge, good luck!</td>', 'Excellent image, the best i''ve seen so far int his challenge, good luck!', '2010-05-05 08:22:30.000000', NULL, 1),
(5991768, 878432, 23394, '<td valign="top">nice try, but 1) you lost your focus, and 2) your background is way too cluttered.  try shooting from a lower perspective.</td>', 'nice try, but 1) you lost your focus, and 2) your background is way too cluttered.  try shooting from a lower perspective.', '2010-05-05 08:24:15.000000', NULL, 1),
(5991771, 878402, 23394, '<td valign="top">way cool!  too bad you didn''t get the hand-off...</td>', 'way cool!  too bad you didn''t get the hand-off...', '2010-05-05 08:25:21.000000', NULL, 1),
(5991773, 878064, 23394, '<td valign="top">nicely done.</td>', 'nicely done.', '2010-05-05 08:25:45.000000', NULL, 1),
(5991775, 877710, 23394, '<td valign="top">man, you''ve got balls...</td>', 'man, you''ve got balls...', '2010-05-05 08:26:03.000000', NULL, 1),
(5991779, 878416, 23394, '<td valign="top">nice idea, just wish it was a little sharper and that there was more of a sense of subject.</td>', 'nice idea, just wish it was a little sharper and that there was more of a sense of subject.', '2010-05-05 08:27:20.000000', NULL, 1),
(5991780, 877606, 23394, '<td valign="top">nicely done.</td>', 'nicely done.', '2010-05-05 08:27:51.000000', NULL, 1),
(5991788, 878016, 23394, '<td valign="top">"Not Another Little League Photo"...yeah, just another snapshot of something related to sports ;-)</td>', '"Not Another Little League Photo"...yeah, just another snapshot of something related to sports ;-)', '2010-05-05 08:29:12.000000', NULL, 1),
(5991790, 877815, 23394, '<td valign="top">nice!</td>', 'nice!', '2010-05-05 08:30:01.000000', NULL, 1),
(5991794, 876433, 23394, '<td valign="top">nice moment, just wish you could have cropped down to just the pitcher, though.</td>', 'nice moment, just wish you could have cropped down to just the pitcher, though.', '2010-05-05 08:30:48.000000', NULL, 1),
(5991796, 877928, 23394, '<td valign="top">if you really want these shots to connect, you''ve got to get a lower perspective.  either sit or kneel.  just do whatever you can to avoid shooting down on your subjects.</td>', 'if you really want these shots to connect, you''ve got to get a lower perspective.  either sit or kneel.  just do whatever you can to avoid shooting down on your subjects.', '2010-05-05 08:32:04.000000', NULL, 1),
(5991797, 876523, 23394, '<td valign="top">nice idea, but too much visual clutter and not enough perspective to make it interesting.</td>', 'nice idea, but too much visual clutter and not enough perspective to make it interesting.', '2010-05-05 08:32:42.000000', NULL, 1),
(5991799, 878438, 23394, '<td valign="top">nice enough moment.  could be improved by a lower perspective (if possible)</td>', 'nice enough moment.  could be improved by a lower perspective (if possible)', '2010-05-05 08:34:05.000000', NULL, 1),
(5991801, 878399, 23394, '<td valign="top">awesome artwork!  i''m quite sure you''re generating some serious buzz about the artwork rules, though...</td>', 'awesome artwork!  i''m quite sure you''re generating some serious buzz about the artwork rules, though...', '2010-05-05 08:35:25.000000', NULL, 1),
(5991806, 878024, 23394, '<td valign="top">honestly, you blew it with the crop.  if you had cropped all the way into the upper torsos of the guy with the ball and the tackler, you would have had a real winner...</td>', 'honestly, you blew it with the crop.  if you had cropped all the way into the upper torsos of the guy with the ball and the tackler, you would have had a real winner...', '2010-05-05 08:37:05.000000', NULL, 1),
(5991813, 877240, 23394, '<td valign="top">this has potential, but the big boat really takes away from it.  it also could benefit from advanced editing (but that''s beyond your control here).</td>', 'this has potential, but the big boat really takes away from it.  it also could benefit from advanced editing (but that''s beyond your control here).', '2010-05-05 08:38:48.000000', NULL, 1),
(5991815, 878336, 64670, '<td valign="top">WOW - I just saw this on the news here in Australia!</td>', 'WOW - I just saw this on the news here in Australia!', '2010-05-05 08:39:16.000000', NULL, 1),
(5991818, 875415, 23394, '<td valign="top">great moment spoiled by a lack of razor sharp focus.</td>', 'great moment spoiled by a lack of razor sharp focus.', '2010-05-05 08:39:30.000000', NULL, 1),
