(5992597, 878336, 92577, '<td valign="top">OMG I just saw this on the TV news here in the UK. Amazing.</td>', 'OMG I just saw this on the TV news here in the UK. Amazing.', '2010-05-05 16:24:59.000000', NULL, 1),
(5992601, 877710, 92577, '<td valign="top">Good shot ( I think I know where I''m going wrong with my swing now)</td>', 'Good shot ( I think I know where I''m going wrong with my swing now)', '2010-05-05 16:28:58.000000', NULL, 1),
(5992611, 877347, 92577, '<td valign="top">like the way the tree and the man are leaning back ''together''</td>', 'like the way the tree and the man are leaning back ''together''', '2010-05-05 16:32:08.000000', NULL, 1),
(5992632, 878343, 75585, '<td valign="top">I like this shot a lot - I would have loved it if it were not a staged shot with flash.  Still a nice job; however, in this challenge I am voting those that had no control over light higher than those that created action in a controlled environment as I believe that was part of the ''challenge''.</td>', 'I like this shot a lot - I would have loved it if it were not a staged shot with flash.  Still a nice job; however, in this challenge I am voting those that had no control over light higher than those that created action in a controlled environment as I believe that was part of the ''challenge''.', '2010-05-05 16:45:12.000000', NULL, 1),
(5992636, 878440, 75585, '<td valign="top">If there were a bit more space under her foot it would have felt more balanced for me.</td>', 'If there were a bit more space under her foot it would have felt more balanced for me.', '2010-05-05 16:46:16.000000', NULL, 1),
(5992642, 875993, 75585, '<td valign="top">Great shot - a bit bright on the top (backboard area) but controlling light outside is difficult with reflective surfaces.</td>', 'Great shot - a bit bright on the top (backboard area) but controlling light outside is difficult with reflective surfaces.', '2010-05-05 16:47:27.000000', NULL, 1),
(5992651, 878320, 92577, '<td valign="top">great drama</td>', 'great drama', '2010-05-05 16:56:12.000000', NULL, 1),
(5992660, 878237, 75585, '<td valign="top">I like this idea - it is pretty cute.  For me this challenge was about capturing an action shot without controlling the light so this image didn''t meet that aspect for me but it is still cute.</td>', 'I like this idea - it is pretty cute.  For me this challenge was about capturing an action shot without controlling the light so this image didn''t meet that aspect for me but it is still cute.', '2010-05-05 17:05:01.000000', NULL, 1),
(5992661, 876570, 75585, '<td valign="top">A little too  much topaz for me.</td>', 'A little too  much topaz for me.', '2010-05-05 17:05:21.000000', NULL, 1),
(5992665, 877696, 75585, '<td valign="top">I think this is a nice idea and would have worked a lot better in a natural setting.</td>', 'I think this is a nice idea and would have worked a lot better in a natural setting.', '2010-05-05 17:07:48.000000', NULL, 1),
(5992679, 878194, 92577, '<td valign="top">looks good in mono</td>', 'looks good in mono', '2010-05-05 17:18:50.000000', NULL, 1),
(5992738, 876949, 109818, '<td valign="top">those hairy legs are what ruined it for me...</td>', 'those hairy legs are what ruined it for me...', '2010-05-05 18:09:24.000000', NULL, 1),
(5992779, 878336, 37845, '<td valign="top">I saw this on the news yesterday... crazy that he got tased in front of thousands. Good photojournalism.</td>', 'I saw this on the news yesterday... crazy that he got tased in front of thousands. Good photojournalism.', '2010-05-05 18:34:13.000000', NULL, 1),
(5992783, 878181, 114219, '<td valign="top">cool shot....looks overly processed IMHO</td>', 'cool shot....looks overly processed IMHO', '2010-05-05 18:36:09.000000', NULL, 1),
(5992785, 878252, 114219, '<td valign="top">cool idea...I am not sure that the skewed perspective is helping the photo......</td>', 'cool idea...I am not sure that the skewed perspective is helping the photo......', '2010-05-05 18:37:55.000000', NULL, 1),
(5992895, 877745, 45631, '<td valign="top">Good composition, DOF and timed just right.  Well done.</td>', 'Good composition, DOF and timed just right.  Well done.', '2010-05-05 19:45:08.000000', NULL, 1),
(5992903, 877857, 23394, '<td valign="top">if only for uniqueness...killer shot, well done!</td>', 'if only for uniqueness...killer shot, well done!', '2010-05-05 19:49:31.000000', NULL, 1),
(5992910, 878437, 23484, '<td valign="top">Nice capture and I really like the processing. Nice job stopping the action.</td>', 'Nice capture and I really like the processing. Nice job stopping the action.', '2010-05-05 19:50:32.000000', NULL, 1),
(5992911, 878194, 23394, '<td valign="top">my favorite of the genre.  typically, i hate surfing shots, but shots like these are so far above the norm.  excellent work!</td>', 'my favorite of the genre.  typically, i hate surfing shots, but shots like these are so far above the norm.  excellent work!', '2010-05-05 19:50:41.000000', NULL, 1),
(5992915, 878045, 23394, '<td valign="top">killer shot!  you might could have made it pop more, though, but i''m not complaining.  great composition, perfect crop.</td>', 'killer shot!  you might could have made it pop more, though, but i''m not complaining.  great composition, perfect crop.', '2010-05-05 19:51:23.000000', NULL, 1),
(5992916, 878383, 23484, '<td valign="top">That left arm looks like it''s ready to break off. Nice image.</td>', 'That left arm looks like it''s ready to break off. Nice image.', '2010-05-05 19:52:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5992918, 877985, 23394, '<td valign="top">nicely done.  even if it''s a bit soft, it still got my attention.  you might could have pushed it a bit more to make it pop, but all the same, good work.</td>', 'nicely done.  even if it''s a bit soft, it still got my attention.  you might could have pushed it a bit more to make it pop, but all the same, good work.', '2010-05-05 19:52:28.000000', NULL, 1),
(5992919, 878343, 23484, '<td valign="top">Very nice shot and great processing.</td>', 'Very nice shot and great processing.', '2010-05-05 19:52:52.000000', NULL, 1),
(5992921, 878192, 23484, '<td valign="top">Nice catch. Now if he can just get his legs over.</td>', 'Nice catch. Now if he can just get his legs over.', '2010-05-05 19:54:01.000000', NULL, 1),
(5992925, 878285, 23484, '<td valign="top">Great clear shot.</td>', 'Great clear shot.', '2010-05-05 19:55:01.000000', NULL, 1),
(5992929, 878064, 23484, '<td valign="top">Fantastic composition and great angle. A little soft but great image.</td>', 'Fantastic composition and great angle. A little soft but great image.', '2010-05-05 19:56:23.000000', NULL, 1),
(5992931, 878402, 23484, '<td valign="top">Excellent motion panning.</td>', 'Excellent motion panning.', '2010-05-05 19:57:10.000000', NULL, 1),
(5992938, 878207, 23484, '<td valign="top">Nice closeup.</td>', 'Nice closeup.', '2010-05-05 19:58:31.000000', NULL, 1),
(5992945, 878137, 23394, '<td valign="top">nice stop action, good perspective.  you''re heading in the right direction.  most of the time, the quality of action shots depends on the level of play that you''re shooting.  playground shots rarely have a lot of appeal.  doesn''t mean that getting a great shot is impossible, but you have to work at it more.  you have to know what to look for, anticipate, and be patient.</td>', 'nice stop action, good perspective.  you''re heading in the right direction.  most of the time, the quality of action shots depends on the level of play that you''re shooting.  playground shots rarely have a lot of appeal.  doesn''t mean that getting a great shot is impossible, but you have to work at it more.  you have to know what to look for, anticipate, and be patient.', '2010-05-05 20:00:19.000000', NULL, 1),
(5992946, 878081, 23394, '<td valign="top">love the perspective (one of my favorites).  image seems a little flat, though.</td>', 'love the perspective (one of my favorites).  image seems a little flat, though.', '2010-05-05 20:01:02.000000', NULL, 1),
(5992949, 878192, 23394, '<td valign="top">very, very nice; one of the best of the track shots entered in the challenge.  you managed to do one thing most people fail, and that is to get a clean background...kudos!  great moment, great graphic image.</td>', 'very, very nice; one of the best of the track shots entered in the challenge.  you managed to do one thing most people fail, and that is to get a clean background...kudos!  great moment, great graphic image.', '2010-05-05 20:03:02.000000', NULL, 1),
(5992951, 878417, 23394, '<td valign="top">one of the better little league shots.  not completely sold on the imbalanced composition, though.</td>', 'one of the better little league shots.  not completely sold on the imbalanced composition, though.', '2010-05-05 20:03:55.000000', NULL, 1),
(5992953, 878324, 23394, '<td valign="top">nice capture.  a little soft and a little flat, but that''s hard to overcome in fading light and under basic editing rules.  you might also try a little lower perspective, if only to be able to see up under the helmets.</td>', 'nice capture.  a little soft and a little flat, but that''s hard to overcome in fading light and under basic editing rules.  you might also try a little lower perspective, if only to be able to see up under the helmets.', '2010-05-05 20:05:07.000000', NULL, 1),
(5992956, 878440, 23394, '<td valign="top">nice stop action, but bad positioning by you...you need to find a spot to get the pitcher isolated, without any other players behind her.  not always easy, but makes the difference between a good shot and a great shot.  that''s a tough moment to capture, as it is; you might as well make it pay off.</td>', 'nice stop action, but bad positioning by you...you need to find a spot to get the pitcher isolated, without any other players behind her.  not always easy, but makes the difference between a good shot and a great shot.  that''s a tough moment to capture, as it is; you might as well make it pay off.', '2010-05-05 20:06:45.000000', NULL, 1),
(5992958, 878095, 23394, '<td valign="top">nice enough action grab, but looks a little soft.  nice colors, good perspective.  the bridge is a distraction.</td>', 'nice enough action grab, but looks a little soft.  nice colors, good perspective.  the bridge is a distraction.', '2010-05-05 20:07:48.000000', NULL, 1),
(5992967, 878227, 23394, '<td valign="top">nice moment, good perspective.  seems a little flat/soft.</td>', 'nice moment, good perspective.  seems a little flat/soft.', '2010-05-05 20:10:40.000000', NULL, 1),
(5992970, 878209, 23394, '<td valign="top">not bad.</td>', 'not bad.', '2010-05-05 20:12:14.000000', NULL, 1),
(5992971, 875544, 23394, '<td valign="top">very nicely done!  excellent panning, great colors.</td>', 'very nicely done!  excellent panning, great colors.', '2010-05-05 20:12:51.000000', NULL, 1),
(5992972, 875643, 23394, '<td valign="top">nicely observed</td>', 'nicely observed', '2010-05-05 20:13:50.000000', NULL, 1),
(5992974, 876452, 23394, '<td valign="top">nice work.  these are tough shots to get and you pretty much nailed it.</td>', 'nice work.  these are tough shots to get and you pretty much nailed it.', '2010-05-05 20:14:27.000000', NULL, 1),
(5992977, 878336, 23394, '<td valign="top">not sure what to make of this, but it''s different.  i''m sure is not what you were expecting when you headed out to the ballpark...</td>', 'not sure what to make of this, but it''s different.  i''m sure is not what you were expecting when you headed out to the ballpark...', '2010-05-05 20:15:15.000000', NULL, 1),
(5992980, 877237, 23394, '<td valign="top">nice exposure.  that''s a lot of opportunity to blow the highlight, but i''m seeing great detail in the foam.  nice work.</td>', 'nice exposure.  that''s a lot of opportunity to blow the highlight, but i''m seeing great detail in the foam.  nice work.', '2010-05-05 20:16:11.000000', NULL, 1),
(5992983, 878251, 23394, '<td valign="top">cool shot!</td>', 'cool shot!', '2010-05-05 20:16:23.000000', NULL, 1),
(5992988, 877280, 23394, '<td valign="top">excellent shot destroyed by a bad crop.  you should have cropped in to right under the elbow; all that torso space is just wasted.  the intensity in the faces and the moment you captured could have put you near the top of the challenge...</td>', 'excellent shot destroyed by a bad crop.  you should have cropped in to right under the elbow; all that torso space is just wasted.  the intensity in the faces and the moment you captured could have put you near the top of the challenge...', '2010-05-05 20:18:05.000000', NULL, 1),
(5992991, 878018, 23394, '<td valign="top">pleasant to look at, but kinda boring in a screen-saver kinda way...</td>', 'pleasant to look at, but kinda boring in a screen-saver kinda way...', '2010-05-05 20:18:46.000000', NULL, 1),
(5992992, 876570, 23394, '<td valign="top">love it!  wish you could have made it pop more, though.  love the gritty feel.  nice work!</td>', 'love it!  wish you could have made it pop more, though.  love the gritty feel.  nice work!', '2010-05-05 20:19:25.000000', NULL, 1),
(5992995, 876508, 23394, '<td valign="top">EXCELLENT!  one of the best of the youth sport shots in the challenge!  great perspective, wonderful moment.  really gives you the feeling of being in the middle of it.</td>', 'EXCELLENT!  one of the best of the youth sport shots in the challenge!  great perspective, wonderful moment.  really gives you the feeling of being in the middle of it.', '2010-05-05 20:20:37.000000', NULL, 1),
(5993000, 877984, 23394, '<td valign="top">yes, it tells the story, but don''t you hate it when you get there a half-second too late...</td>', 'yes, it tells the story, but don''t you hate it when you get there a half-second too late...', '2010-05-05 20:21:38.000000', NULL, 1),
(5993001, 877818, 23394, '<td valign="top">excellent work!  love the tones.  great moment.</td>', 'excellent work!  love the tones.  great moment.', '2010-05-05 20:22:07.000000', NULL, 1),
(5993009, 877624, 23394, '<td valign="top">i love it, but doubt if the rest of dpc does...<br/> <br/>as far as challenges go, you probably could have worked with the same type shot, but have shot tighter on the runners and included less of the background.</td>', 'i love it, but doubt if the rest of dpc does... as far as challenges go, you probably could have worked with the same type shot, but have shot tighter on the runners and included less of the background.', '2010-05-05 20:26:50.000000', NULL, 1),
(5993090, 878313, 28882, '<td valign="top">how amazing is this?!</td>', 'how amazing is this?!', '2010-05-05 21:22:33.000000', NULL, 1),
(5993120, 876404, 23484, '<td valign="top">Nice image. Very well composed.</td>', 'Nice image. Very well composed.', '2010-05-05 21:51:28.000000', NULL, 1),
(5993121, 877245, 23484, '<td valign="top">Love the B&amp;W on this.</td>', 'Love the B&W on this.', '2010-05-05 21:52:00.000000', NULL, 1),
(5993124, 876904, 23484, '<td valign="top">this image really shows the intensity. Nice job.</td>', 'this image really shows the intensity. Nice job.', '2010-05-05 21:52:41.000000', NULL, 1),
(5993134, 878122, 23394, '<td valign="top">this is a good shot, but it could have been a great one if you''d shot from a lower perspective.  as is, it''s a shot anyone with a decent camera could have taken.  shoot tighter and take me into the action.  show me something i can''t see from the sidelines.</td>', 'this is a good shot, but it could have been a great one if you''d shot from a lower perspective.  as is, it''s a shot anyone with a decent camera could have taken.  shoot tighter and take me into the action.  show me something i can''t see from the sidelines.', '2010-05-05 21:59:42.000000', NULL, 1),
(5993135, 876910, 23394, '<td valign="top">nicely done.</td>', 'nicely done.', '2010-05-05 21:59:45.000000', NULL, 1),
(5993136, 877745, 23394, '<td valign="top">nice work, especially in those conditions.  isn''t it great, having equipment that can handle lighting like that?</td>', 'nice work, especially in those conditions.  isn''t it great, having equipment that can handle lighting like that?', '2010-05-05 21:59:46.000000', NULL, 1),
(5993140, 878108, 23394, '<td valign="top">cool shot.  even though this is a basic challenge, i think you could have pushed it more to make it really pop.  shadow/highlight is legal under basic and you could have really used that to your advantage.</td>', 'cool shot.  even though this is a basic challenge, i think you could have pushed it more to make it really pop.  shadow/highlight is legal under basic and you could have really used that to your advantage.', '2010-05-05 22:00:55.000000', NULL, 1),
(5993144, 876550, 23394, '<td valign="top">nice image, great composition, a little soft on the edges.  gotta love having the opportunity to shoot stuff like this ;-)</td>', 'nice image, great composition, a little soft on the edges.  gotta love having the opportunity to shoot stuff like this ;-)', '2010-05-05 22:02:37.000000', NULL, 1),
(5993147, 876555, 23394, '<td valign="top">killer moment.  you can''t plan stuff like that; ya just gotta be there.  nice work.</td>', 'killer moment.  you can''t plan stuff like that; ya just gotta be there.  nice work.', '2010-05-05 22:03:50.000000', NULL, 1),
(5993148, 878239, 23394, '<td valign="top">nice work, especially from the bleachers.  love the colors, and nice job with the exposure...pretty tricky with that much sunlight.</td>', 'nice work, especially from the bleachers.  love the colors, and nice job with the exposure...pretty tricky with that much sunlight.', '2010-05-05 22:04:05.000000', NULL, 1),
(5993149, 876423, 23394, '<td valign="top">wow!  nice work!  there are only a handful of people on this site that are capable of a shot like that and you''re one of them.  excellent!</td>', 'wow!  nice work!  there are only a handful of people on this site that are capable of a shot like that and you''re one of them.  excellent!', '2010-05-05 22:04:54.000000', NULL, 1),
(5993150, 875981, 23394, '<td valign="top">cool shot.  i almost wish i could see it toned bw.</td>', 'cool shot.  i almost wish i could see it toned bw.', '2010-05-05 22:06:00.000000', NULL, 1),
(5993154, 878354, 23394, '<td valign="top">nice moment, good perspective.  you might want to take a look at this using shadow/highlights.  you can still make it pop, but you lose the raccoon effect of the harsh sunlight.</td>', 'nice moment, good perspective.  you might want to take a look at this using shadow/highlights.  you can still make it pop, but you lose the raccoon effect of the harsh sunlight.', '2010-05-05 22:08:33.000000', NULL, 1),
(5993162, 877108, 23394, '<td valign="top">technically, this is a fine shot; aesthetically, it''s not that interesting.  these shots a good for parents, good for newspapers doing articles about individuals, but, they are no good for dpc challenges.  this is something that could be captured by nearly anyone with a decent camera and lens; if you want to score higher, you''ve got to do something that can''t be done by just anyone...</td>', 'technically, this is a fine shot; aesthetically, it''s not that interesting.  these shots a good for parents, good for newspapers doing articles about individuals, but, they are no good for dpc challenges.  this is something that could be captured by nearly anyone with a decent camera and lens; if you want to score higher, you''ve got to do something that can''t be done by just anyone...', '2010-05-05 22:12:01.000000', NULL, 1),
(5993166, 876787, 23394, '<td valign="top">nice enough shot.  you might have cropped out the roughage at the top, though.</td>', 'nice enough shot.  you might have cropped out the roughage at the top, though.', '2010-05-05 22:13:25.000000', NULL, 1),
(5993167, 877244, 103150, '<td valign="top">would be better without the bicyclist going through</td>', 'would be better without the bicyclist going through', '2010-05-05 22:13:33.000000', NULL, 1),
(5993173, 875981, 103150, '<td valign="top">drugs and sports don''t mix</td>', 'drugs and sports don''t mix', '2010-05-05 22:14:43.000000', NULL, 1),
(5993176, 878444, 23394, '<td valign="top">cool shot.  wouldn''t it have been neat if you could have more shadow further down the rock?</td>', 'cool shot.  wouldn''t it have been neat if you could have more shadow further down the rock?', '2010-05-05 22:15:48.000000', NULL, 1),
(5993182, 878285, 23394, '<td valign="top">ouch.  excellent work, all the way around.  i''ll be surprised if dpc can''t top-10 this.</td>', 'ouch.  excellent work, all the way around.  i''ll be surprised if dpc can''t top-10 this.', '2010-05-05 22:16:53.000000', NULL, 1),
(5993186, 878223, 23394, '<td valign="top">nice work.  you might try shooting from a lower perspective and shooting a little tighter.  take the viewers into the action that they can''t see from the sidelines.</td>', 'nice work.  you might try shooting from a lower perspective and shooting a little tighter.  take the viewers into the action that they can''t see from the sidelines.', '2010-05-05 22:18:42.000000', NULL, 1),
(5993192, 878006, 103150, '<td valign="top">wow, this makes me dizzy</td>', 'wow, this makes me dizzy', '2010-05-05 22:20:52.000000', NULL, 1),
(5993194, 877932, 23394, '<td valign="top">dang!  that ref''s butt is right in the way!  hate it when that ruins what would otherwise be a killer shot.</td>', 'dang!  that ref''s butt is right in the way!  hate it when that ruins what would otherwise be a killer shot.', '2010-05-05 22:22:02.000000', NULL, 1),
(5993195, 878246, 23394, '<td valign="top">great moment.  a shame that your focus was off.</td>', 'great moment.  a shame that your focus was off.', '2010-05-05 22:22:43.000000', NULL, 1),
(5993254, 878313, 97270, '<td valign="top">I wouldn''t change anything in this image. gets a perfect 10 from me!</td>', 'I wouldn''t change anything in this image. gets a perfect 10 from me!', '2010-05-05 23:01:55.000000', NULL, 1),
(5993255, 876198, 97270, '<td valign="top">The day I can take shots like this one, I will go run in the streets screaming your name;-) <br/> <br/>Well done. Good composition, perfect timing, perfect reds, and excellent drops-resolution.<br/> <br/>A 10 from me.</td>', 'The day I can take shots like this one, I will go run in the streets screaming your name;-)  Well done. Good composition, perfect timing, perfect reds, and excellent drops-resolution. A 10 from me.', '2010-05-05 23:03:12.000000', NULL, 1),
(5993257, 878194, 97270, '<td valign="top">This picture should be used as an example in teaching people about how to compose and capture good pictures, before they go into mega pixel and color-vividity battle.<br/> <br/>Excellent job! One of my top 10s in this challenge.</td>', 'This picture should be used as an example in teaching people about how to compose and capture good pictures, before they go into mega pixel and color-vividity battle. Excellent job! One of my top 10s in this challenge.', '2010-05-05 23:04:21.000000', NULL, 1),
(5993260, 878068, 97270, '<td valign="top">This is -not- an extraordinary picture technically. But it has personality. And that''s exactly why it gets a 9 from me. Well done!</td>', 'This is -not- an extraordinary picture technically. But it has personality. And that''s exactly why it gets a 9 from me. Well done!', '2010-05-05 23:05:19.000000', NULL, 1),
(5993264, 877245, 97270, '<td valign="top">Oh what would I not give to capture a moment like this. Super, my friend! My only complain is about the lack of details towards the right bottom corner, but I understand this is a basic editing challenge and it will be hard to get both ends of spectrum in perfect balance with the allowed editing steps. <br/> <br/>You get a 9 from me.</td>', 'Oh what would I not give to capture a moment like this. Super, my friend! My only complain is about the lack of details towards the right bottom corner, but I understand this is a basic editing challenge and it will be hard to get both ends of spectrum in perfect balance with the allowed editing steps.  You get a 9 from me.', '2010-05-05 23:07:27.000000', NULL, 1),
(5993269, 878064, 97270, '<td valign="top">At a glance, I thought this is another ordinary shot. But looking at it closely, I can tell how technically difficult if must have been, with you lying so close to the dude in action. And you got a perfect angle, great composition. 9/10.</td>', 'At a glance, I thought this is another ordinary shot. But looking at it closely, I can tell how technically difficult if must have been, with you lying so close to the dude in action. And you got a perfect angle, great composition. 9/10.', '2010-05-05 23:09:54.000000', NULL, 1),
(5993273, 878024, 97270, '<td valign="top">This is like a painting. the guy cut-off in the corner is a slight distraction, but not enough to take away the story you are telling. What sharpness, what DOF. Bravo my friend!</td>', 'This is like a painting. the guy cut-off in the corner is a slight distraction, but not enough to take away the story you are telling. What sharpness, what DOF. Bravo my friend!', '2010-05-05 23:13:34.000000', NULL, 1),
(5993275, 877064, 45524, '<td valign="top">Not a fan of the extreme tilt on this image. Decent pan job though.</td>', 'Not a fan of the extreme tilt on this image. Decent pan job though.', '2010-05-05 23:14:05.000000', NULL, 1),
(5993280, 878246, 97270, '<td valign="top">Symmetry. DOF. Moment. Exquisite! 9/10.</td>', 'Symmetry. DOF. Moment. Exquisite! 9/10.', '2010-05-05 23:16:03.000000', NULL, 1),
(5993281, 878320, 45524, '<td valign="top">I''d have to say this is a Skip image. If not you have emulated his style pretty well.</td>', 'I''d have to say this is a Skip image. If not you have emulated his style pretty well.', '2010-05-05 23:16:18.000000', NULL, 1),
(5993283, 878270, 97270, '<td valign="top">I do not know if this is the raw color scheme of this image, but I really do love it this way. There are leading lines, although not prominent. There is blur, but that is expected. Good job! 8/10.</td>', 'I do not know if this is the raw color scheme of this image, but I really do love it this way. There are leading lines, although not prominent. There is blur, but that is expected. Good job! 8/10.', '2010-05-05 23:17:11.000000', NULL, 1),
(5993286, 875544, 97270, '<td valign="top">I do not understand the title, especially the ''gone'' reference. Regardless, this is a hard to capture image, I respect that. I like the spirit of it. 8/10.</td>', 'I do not understand the title, especially the ''gone'' reference. Regardless, this is a hard to capture image, I respect that. I like the spirit of it. 8/10.', '2010-05-05 23:18:31.000000', NULL, 1),
(5993287, 877793, 97270, '<td valign="top">Oh boy! The only reason this is not getting a 10 from me is because of the cropped head. Everything else is just perfect... may be a little zooming out would have helped pull in the splash more. 8/10.</td>', 'Oh boy! The only reason this is not getting a 10 from me is because of the cropped head. Everything else is just perfect... may be a little zooming out would have helped pull in the splash more. 8/10.', '2010-05-05 23:19:29.000000', NULL, 1),
(5993288, 875992, 97270, '<td valign="top">Great capture. All the cables and cars and buildings in the background do not bother me. Yes, it''s that effective! I love that you chose to go B&amp;W. You get a 9/10.</td>', 'Great capture. All the cables and cars and buildings in the background do not bother me. Yes, it''s that effective! I love that you chose to go B&W. You get a 9/10.', '2010-05-05 23:20:32.000000', NULL, 1),
(5993292, 877710, 97270, '<td valign="top">Not really sure if I wanted to see a naked bum playing golf, but in the spirit of good photography, I will take it. Sepia does good justice here. I would just have wished for the ''action'' to be caught more instantly (frozen e.g.). Good job! 8/10.</td>', 'Not really sure if I wanted to see a naked bum playing golf, but in the spirit of good photography, I will take it. Sepia does good justice here. I would just have wished for the ''action'' to be caught more instantly (frozen e.g.). Good job! 8/10.', '2010-05-05 23:22:57.000000', NULL, 1),
(5993294, 877710, 45524, '<td valign="top">When yelling four does that indicate incoming ball or or a set of them.........</td>', 'When yelling four does that indicate incoming ball or or a set of them.........', '2010-05-05 23:24:16.000000', NULL, 1),
(5993295, 878416, 97270, '<td valign="top">Ok. Besides the good parts (sharp, varying DOFs, splash, colors), this picture doesn''t appeal to me much. I do see it tells you a story about competitiveness. But it''s not quite hitting the spot. Perhaps it''s the composition? I don''t know. A 7 from me.</td>', 'Ok. Besides the good parts (sharp, varying DOFs, splash, colors), this picture doesn''t appeal to me much. I do see it tells you a story about competitiveness. But it''s not quite hitting the spot. Perhaps it''s the composition? I don''t know. A 7 from me.', '2010-05-05 23:24:42.000000', NULL, 1),
(5993297, 875981, 97270, '<td valign="top">This would have been a 10 pointer if only the shutter speed was higher (to get more ''frozen in time'' effect). I can give examples of other images once the challenge is over. Regardless, these pics are hard to shoot. I respect the composition, the exposure, and give it 8/10. Perhaps it would do good in B&amp;W? Just a thought.</td>', 'This would have been a 10 pointer if only the shutter speed was higher (to get more ''frozen in time'' effect). I can give examples of other images once the challenge is over. Regardless, these pics are hard to shoot. I respect the composition, the exposure, and give it 8/10. Perhaps it would do good in B&W? Just a thought.', '2010-05-05 23:26:40.000000', NULL, 1),
(5993298, 877992, 97270, '<td valign="top">Ok. I know it''s noisy. It''s colorless. It''s ''actor''-less. But it is symmetric, and it is telling a story (of a dream). Just for that, you get 8/10.</td>', 'Ok. I know it''s noisy. It''s colorless. It''s ''actor''-less. But it is symmetric, and it is telling a story (of a dream). Just for that, you get 8/10.', '2010-05-05 23:27:35.000000', NULL, 1),
(5993303, 877280, 97270, '<td valign="top">This is an ordinary picture in every way.. EXCEPT the personality it depicts. What a capture! 8/10.</td>', 'This is an ordinary picture in every way.. EXCEPT the personality it depicts. What a capture! 8/10.', '2010-05-05 23:29:03.000000', NULL, 1),
(5993304, 876910, 97270, '<td valign="top">Sharp. Clear. Centered. Symmetric. Would have given a bit more of perspective if it was taken zoomed out a little bit IMHO, OR if the actor was making eye contact. Good job regardless. 8/10.</td>', 'Sharp. Clear. Centered. Symmetric. Would have given a bit more of perspective if it was taken zoomed out a little bit IMHO, OR if the actor was making eye contact. Good job regardless. 8/10.', '2010-05-05 23:30:13.000000', NULL, 1),
(5993308, 877620, 97270, '<td valign="top">Aye aye aye. Now this is a story in a picture:-) What great way to captures a dozen lil hearts, their ambitions, and the colors around them. Excellent! 8/10.</td>', 'Aye aye aye. Now this is a story in a picture:-) What great way to captures a dozen lil hearts, their ambitions, and the colors around them. Excellent! 8/10.', '2010-05-05 23:31:17.000000', NULL, 1),
(5993312, 877827, 97270, '<td valign="top">Ok. Technical shortcomings apart (blur, hard exposure due to Sun, busy background etc.), this is a pretty neat picture in the sense of the competitive spirit it depicts. Well done. 7/10.</td>', 'Ok. Technical shortcomings apart (blur, hard exposure due to Sun, busy background etc.), this is a pretty neat picture in the sense of the competitive spirit it depicts. Well done. 7/10.', '2010-05-05 23:33:58.000000', NULL, 1),
(5993314, 878097, 97270, '<td valign="top">Good job there! It would have been more effective had the red lines acted as leading lines (rising up from one corner). Regardless, it''s a very good shot. 8/10.</td>', 'Good job there! It would have been more effective had the red lines acted as leading lines (rising up from one corner). Regardless, it''s a very good shot. 8/10.', '2010-05-05 23:34:59.000000', NULL, 1),
(5993315, 876555, 97270, '<td valign="top">Beauty! What a capture mate (or matess:-). Sharp, in focus, good composition. You get an 8/10.</td>', 'Beauty! What a capture mate (or matess:-). Sharp, in focus, good composition. You get an 8/10.', '2010-05-05 23:35:50.000000', NULL, 1),
(5993317, 877244, 114225, '<td valign="top">Very interesting scene. I don''t believe I''ve ever scene sidewalk weightlifting before.<br/> <br/>I think I would have liked this better without the bicyclist.</td>', 'Very interesting scene. I don''t believe I''ve ever scene sidewalk weightlifting before. I think I would have liked this better without the bicyclist.', '2010-05-05 23:36:18.000000', NULL, 1),
(5993319, 877244, 97270, '<td valign="top">Loved how you wanted to depict the focus as a blurry cyclist, along with other parts of the scene telling a story. Good job! 8/10.</td>', 'Loved how you wanted to depict the focus as a blurry cyclist, along with other parts of the scene telling a story. Good job! 8/10.', '2010-05-05 23:37:17.000000', NULL, 1),
(5993321, 878207, 114225, '<td valign="top">Great stop action shot. I like how you can see the reflection of the sky in his helmet. I do kind of wish I could see the glove of the first baseman (this looks like he is trying to get picked off first).</td>', 'Great stop action shot. I like how you can see the reflection of the sky in his helmet. I do kind of wish I could see the glove of the first baseman (this looks like he is trying to get picked off first).', '2010-05-05 23:37:37.000000', NULL, 1),
(5993324, 878324, 114225, '<td valign="top">Nice composition. My eye instantly went to the runner, who is out of focus. Thus, I wonder if it would look even better with him in focus instead of the first baseman.</td>', 'Nice composition. My eye instantly went to the runner, who is out of focus. Thus, I wonder if it would look even better with him in focus instead of the first baseman.', '2010-05-05 23:38:37.000000', NULL, 1),
(5993325, 878382, 97270, '<td valign="top">Ok on a second look, you get an upgrade from 8 to 9. Marvelous! There''s a story in there. And you tell it so nicely. Enjoy your 9!</td>', 'Ok on a second look, you get an upgrade from 8 to 9. Marvelous! There''s a story in there. And you tell it so nicely. Enjoy your 9!', '2010-05-05 23:39:11.000000', NULL, 1),
(5993326, 877296, 114225, '<td valign="top">Nice idea. I like the colors. I wish the ball was a bit more stopped (less blurred).</td>', 'Nice idea. I like the colors. I wish the ball was a bit more stopped (less blurred).', '2010-05-05 23:39:26.000000', NULL, 1),
(5993327, 878081, 114225, '<td valign="top">Nice capture of guys having fun without the need for uniforms and all that.</td>', 'Nice capture of guys having fun without the need for uniforms and all that.', '2010-05-05 23:40:17.000000', NULL, 1),
(5993328, 878343, 97270, '<td valign="top">Good play of lighting with the subject. I love the slight unsaturation. It would have been a 10-pointer if the ball was in focus more than the subject. Good job! 8/10.</td>', 'Good play of lighting with the subject. I love the slight unsaturation. It would have been a 10-pointer if the ball was in focus more than the subject. Good job! 8/10.', '2010-05-05 23:40:35.000000', NULL, 1),
(5993329, 877927, 114225, '<td valign="top">Cool idea. I wonder if it could have been a bit better without the background elements (except the sky/clouds).</td>', 'Cool idea. I wonder if it could have been a bit better without the background elements (except the sky/clouds).', '2010-05-05 23:41:23.000000', NULL, 1),
(5993331, 877909, 97270, '<td valign="top">How in the world did you shoot this? Where was the camera? Good capture! 8/10.</td>', 'How in the world did you shoot this? Where was the camera? Good capture! 8/10.', '2010-05-05 23:41:46.000000', NULL, 1),
(5993332, 877818, 114225, '<td valign="top">Wow, excellent capture. Love the face and the concentration of his eyes on the ball.</td>', 'Wow, excellent capture. Love the face and the concentration of his eyes on the ball.', '2010-05-05 23:41:56.000000', NULL, 1),
(5993333, 877751, 97270, '<td valign="top">A beauty! Would have upgraded it to a 10 if the rider had his face visible. 8/10.</td>', 'A beauty! Would have upgraded it to a 10 if the rider had his face visible. 8/10.', '2010-05-05 23:42:31.000000', NULL, 1),
(5993334, 878303, 114225, '<td valign="top">Nice choice for a frozen moment. It really shows the physical aspect of the game.</td>', 'Nice choice for a frozen moment. It really shows the physical aspect of the game.', '2010-05-05 23:43:06.000000', NULL, 1),
