(5995818, 878437, 113278, '<td valign="top">Great shot, top 3 for me.</td>', 'Great shot, top 3 for me.', '2010-05-07 15:00:11.000000', NULL, 1),
(5995853, 878324, 108069, '<td valign="top">Great angle of view. Not many chances at it, I know, but a faster exposure would have captured the look of determination to not get caught off first. But it''s a great capture of a dramatic scene. Nice one.</td>', 'Great angle of view. Not many chances at it, I know, but a faster exposure would have captured the look of determination to not get caught off first. But it''s a great capture of a dramatic scene. Nice one.', '2010-05-07 15:22:39.000000', NULL, 1),
(5995859, 876872, 108069, '<td valign="top">Very cute. Reminds me of my youth, except I was always a lot higher up, and the stadium was next door. Seems to be a bit noisy, but it helps to give it an old-timey feel.</td>', 'Very cute. Reminds me of my youth, except I was always a lot higher up, and the stadium was next door. Seems to be a bit noisy, but it helps to give it an old-timey feel.', '2010-05-07 15:26:26.000000', NULL, 1),
(5995862, 876198, 69368, '<td valign="top">Like to see this on the frontpage! Best in challenge!</td>', 'Like to see this on the frontpage! Best in challenge!', '2010-05-07 15:28:09.000000', NULL, 1),
(5995864, 877928, 108069, '<td valign="top">Wow, that brings back some memories. Great capture of a classic moment in youth baseball. Drama at its best there. Great.</td>', 'Wow, that brings back some memories. Great capture of a classic moment in youth baseball. Drama at its best there. Great.', '2010-05-07 15:28:32.000000', NULL, 1),
