(5995936, 877985, 108069, '<td valign="top">Great shot. Nice tight crop to really get the action instead of focusing on the surrounding scenery. Well done.</td>', 'Great shot. Nice tight crop to really get the action instead of focusing on the surrounding scenery. Well done.', '2010-05-07 16:07:14.000000', NULL, 1),
