INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6002994, 878320, 105130, '<td valign="top">I didn''t vote or comment during this challenge, but this one caught my eye. It''s simply magnificent, no other word for it. Congratulations on the top 10, but I feel it should have ribboned.</td>', 'I didn''t vote or comment during this challenge, but this one caught my eye. It''s simply magnificent, no other word for it. Congratulations on the top 10, but I feel it should have ribboned.', '2010-05-12 04:43:19.000000', NULL, 0),
(6002999, 878383, 67237, '<td valign="top">Congrats on the HM.  <br/>I can''t believe those 1''s, 2''s and 3''s.  But this time is evident those votes came from competitors in the same challenge...just compare these two figures:<br/>NON-PARTICIPANTS Average = 7.4065<br/>PARTICIPANTS Average = 6.4571<br/>A difference of almost ONE FULL POINT is not only statistically irrational and impossible, but gives us more than a clue on how voting patterns are affected by DPL. You were definitely robbed on this one.<br/> <br/>edited to add:<br/>1.- among the top 5 images, you are, by far, the most affected by the difference between non-participant vs. participant avg''s.<br/>2.- about the outtakes you consider too blurry...I like them even more than your entry<br/><br/><i>Message edited by author 2010-05-12 03:58:32.</i></td>', 'Congrats on the HM.  I can''t believe those 1''s, 2''s and 3''s.  But this time is evident those votes came from competitors in the same challenge...just compare these two figures:NON-PARTICIPANTS Average = 7.4065PARTICIPANTS Average = 6.4571A difference of almost ONE FULL POINT is not only statistically irrational and impossible, but gives us more than a clue on how voting patterns are affected by DPL. You were definitely robbed on this one. edited to add:1.- among the top 5 images, you are, by far, the most affected by the difference between non-participant vs. participant avg''s.2.- about the outtakes you consider too blurry...I like them even more than your entry', '2010-05-12 04:44:36.000000', '2010-05-12 04:58:32.000000', 0),
(6003039, 878383, 27845, '<td valign="top">Good work, great finish.</td>', 'Good work, great finish.', '2010-05-12 04:53:15.000000', NULL, 0),
